-- ============================================================
-- Sync catálogo completo de Dálida Beauty & Spa a Supabase
-- Ejecutar en Supabase Studio > SQL Editor (o via psql)
-- Idempotente: puede ejecutarse múltiples veces sin duplicar.
-- ============================================================

-- 1) Columnas necesarias
alter table spanails.categorias add column if not exists icono text;
alter table spanails.servicios  add column if not exists grupo text;

-- 2) Categorías (áreas del catálogo)
on conflict (slug) do update set
  nombre = excluded.nombre,
  descripcion = excluded.descripcion,
  imagen_url = coalesce(spanails.categorias.imagen_url, excluded.imagen_url),
  icono = excluded.icono,
  activo = true;

-- 3) Servicios
with c as (select id, slug from spanails.categorias)
on conflict (slug) do update set
  categoria_id = excluded.categoria_id,
  nombre = excluded.nombre,
  imagen_url = coalesce(excluded.imagen_url, spanails.servicios.imagen_url),
  grupo = excluded.grupo,
  orden = excluded.orden,
  activo = true;

-- 4) Verificación
select count(*) as categorias from spanails.categorias where icono is not null;
select count(*) as servicios from spanails.servicios;